import{Q as h$1,d as I,z as _}from"./chunk-Czdnn5p3.js";var f=[{trackId:`javascript`,questions:[{id:`event-loop-order`,prompt:`В каком порядке выведутся строки?`,code:`~~~js
console.log('1');
setTimeout(() => console.log('2'), 0);
Promise.resolve().then(() => console.log('3'));
console.log('4');
~~~`,options:[`1, 2, 3, 4`,`1, 4, 3, 2`,`1, 4, 2, 3`,`1, 3, 4, 2`],correctIndex:1,explanation:`Синхронный код выполняется первым (1, 4). После него очередь **микрозадач** опустошается полностью (then → 3), и только затем браузер берёт следующую **макрозадачу** — колбэк таймера (2). Подробнее — [Event Loop](/tracks/javascript/event-loop).`},{id:`var-loop`,prompt:`Что выведет код?`,code:`~~~js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i));
}
~~~`,options:[`0, 1, 2`,`3, 3, 3`,`undefined ×3`,`ReferenceError`],correctIndex:1,explanation:"`var` создаёт одну переменную на всю функцию. Все три колбэка замыкают её, а к моменту срабатывания таймеров цикл завершён и `i === 3`. С `let` каждая итерация получила бы свою привязку и вывела бы 0, 1, 2."},{id:`tdz`,prompt:`Что произойдёт при выполнении?`,code:`~~~js
let x = '\u0432\u043D\u0435\u0448\u043D\u044F\u044F';
{
  console.log(x);
  let x = '\u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u044F\u044F';
}
~~~`,options:[`Выведет «внешняя»`,`Выведет undefined`,`ReferenceError`,`Выведет «внутренняя»`],correctIndex:2,explanation:"Внутренняя `x` поднимается в начало блока и затеняет внешнюю, но до строки объявления находится во **временной мёртвой зоне**. Обращение к ней бросает `ReferenceError: Cannot access 'x' before initialization`."},{id:`this-arrow`,prompt:`Что вернёт obj.getArrow()?`,code:`~~~js
const obj = {
  name: 'obj',
  getArrow: () => this?.name,
  getRegular() { return this.name; },
};
~~~`,options:[`'obj'`,`undefined (this модуля)`,`TypeError`,`''`],correctIndex:1,explanation:"Стрелочная функция не имеет собственного `this` и берёт его из окружающей лексической области — здесь это верхний уровень модуля, где `this === undefined`. Метод `getRegular` вернул бы `obj`."},{id:`equality`,prompt:`Какое из выражений вернёт true?`,options:[`NaN === NaN`,`null == 0`,`[] == false`,`'0' === 0`],correctIndex:2,explanation:"При `==` false приводится к 0, массив — к примитиву: `[]` → `''` → 0, поэтому `[] == false` истинно. `NaN` не равен ничему, включая себя; `null` нестрого равен только `undefined`; `===` не приводит типы."},{id:`promise-executor`,prompt:`Что выведется первым?`,code:`~~~js
new Promise((resolve) => {
  console.log('A');
  resolve();
}).then(() => console.log('B'));
console.log('C');
~~~`,options:[`C`,`B`,`A`,`Порядок не определён`],correctIndex:2,explanation:"Функция-executor, переданная в `new Promise`, выполняется **синхронно**. Порядок: A, C, B — then идёт через очередь микрозадач."},{id:`closure-memory`,prompt:`Что такое замыкание?`,options:[`Функция, которая вызывает сама себя`,`Функция вместе со ссылкой на лексическое окружение, в котором она создана`,`Способ закрыть доступ к объекту через Object.freeze`,`Функция, объявленная внутри класса`],correctIndex:1,explanation:"Функция хранит ссылку `[[Environment]]` на окружение создания и видит его переменные даже после выхода из внешней функции. Замыкается **переменная**, а не её значение. Подробнее — [Замыкания](/tracks/javascript/closures)."},{id:`prototype-vs-proto`,prompt:`Чем отличается Fn.prototype от obj.__proto__?`,options:[`Это одно и то же`,`prototype есть у функций и становится [[Prototype]] объектов, созданных через new; __proto__ — прототип конкретного объекта`,`__proto__ есть только у классов`,`prototype — устаревшее свойство, его заменил __proto__`],correctIndex:1,explanation:"После `const u = new User()` верно `Object.getPrototypeOf(u) === User.prototype`. Современный API для работы с прототипом — `Object.getPrototypeOf` / `Object.create`."},{id:`promise-all-settled`,prompt:`Нужно отправить пять независимых запросов и показать результат каждого, даже если часть упала. Что использовать?`,options:[`Promise.all`,`Promise.race`,`Promise.allSettled`,`Promise.any`],correctIndex:2,explanation:"`allSettled` дожидается всех промисов и возвращает статус каждого (`fulfilled` с value или `rejected` с reason). `all` отклоняется при первой ошибке, `race` — первый осевший, `any` — первый успешный."},{id:`microtask-starvation`,prompt:`Почему рекурсивное Promise.resolve().then(loop) подвешивает страницу, а рекурсивный setTimeout(loop) — нет?`,options:[`Промисы выполняются в отдельном потоке`,`Очередь микрозадач опустошается полностью перед рендером, и новые микрозадачи добавляются бесконечно`,`setTimeout автоматически ограничен 60 вызовами в секунду`,`Промисы блокируют сборщик мусора`],correctIndex:1,explanation:`Event loop не перейдёт к рендерингу и обработке ввода, пока очередь микрозадач не пуста. Между макрозадачами (таймерами) браузер успевает рисовать кадры и обрабатывать события.`},{id:`weakmap`,prompt:`Когда стоит использовать WeakMap вместо Map?`,options:[`Когда ключи — строки`,`Когда нужно перебирать записи по порядку`,`Когда нужно хранить данные об объекте, не продлевая его жизнь`,`Когда нужна максимальная скорость`],correctIndex:2,explanation:`WeakMap держит ключи-объекты слабо: когда на объект не остаётся других ссылок, запись удаляется вместе с ним. Ключи — только объекты, коллекцию нельзя перебрать и узнать её размер.`},{id:`esm-live-binding`,prompt:`Модуль counter.js экспортирует let count = 0 и функцию increment(). Что увидит импортирующий модуль после вызова increment()?`,options:[`Всегда 0 — импорт копирует значение`,`Актуальное значение 1 — ESM-импорт это живая привязка`,`Ошибку: импорт нельзя читать после изменения`,`Зависит от сборщика`],correctIndex:1,explanation:"В ES-модулях импорт — ссылка на переменную экспортирующего модуля (live binding). В CommonJS деструктурированный `require` даёт копию на момент импорта."}]},{trackId:`typescript`,questions:[{id:`unknown-vs-any`,prompt:`Чем unknown отличается от any?`,options:[`Ничем, это синонимы`,`С unknown нельзя ничего сделать без сужения типа, any отключает проверки`,`unknown нельзя присвоить значение`,`any безопаснее, потому что поддерживает автодополнение`],correctIndex:1,explanation:"Оба принимают любое значение. Но `any` выключает проверку типов везде, где встречается, а `unknown` запрещает операции, пока вы не сузите тип через `typeof`, `instanceof`, `in` или type guard. Для внешних данных — `unknown`."},{id:`type-vs-interface`,prompt:`Что можно выразить только через type, но не через interface?`,options:[`Объект с методами`,`Объединение типов (union)`,`Необязательные поля`,`Наследование через extends`],correctIndex:1,explanation:"`type` — псевдоним для любого типа: объединений, кортежей, функций, mapped и условных типов. Интерфейс описывает только объекты, зато поддерживает слияние объявлений."},{id:`satisfies`,prompt:`Что делает оператор satisfies?`,code:`~~~ts
const theme = { primary: '#2450b8' } satisfies Record<string, string>;
~~~`,options:[`Приводит тип как as, без проверки`,`Проверяет совместимость значения с типом, сохраняя выведенный (узкий) тип`,`Делает объект readonly`,`Создаёт branded type`],correctIndex:1,explanation:"Аннотация `const x: T` расширяет тип переменной до `T`, `as` не проверяет совместимость, а `satisfies` проверяет и оставляет точный выведенный тип — например, литералы."},{id:`distributive`,prompt:`Чему равен тип R?`,code:`~~~ts
type ToArray<T> = T extends unknown ? T[] : never;
type R = ToArray<string | number>;
~~~`,options:[`(string | number)[]`,`string[] | number[]`,`never`,`unknown[]`],correctIndex:1,explanation:"Условный тип над «голым» параметром дистрибутивен: применяется к каждому члену объединения по отдельности. Чтобы получить `(string | number)[]`, оберните в кортеж: `[T] extends [unknown]`."},{id:`never-exhaustive`,prompt:`Зачем в default-ветке switch вызывают функцию assertNever(value: never)?`,options:[`Чтобы ускорить выполнение`,`Чтобы компилятор сообщил об ошибке, если в union добавят вариант и забудут его обработать`,`Чтобы switch работал со строками`,`Это требование линтера без практического смысла`],correctIndex:1,explanation:"Если все варианты обработаны, в default значение имеет тип `never`. Новый необработанный вариант делает тип не-never, и передача в `assertNever` становится ошибкой компиляции во всех таких местах."},{id:`infer`,prompt:`Что вернёт тип Unpack<Promise<User[]>>?`,code:`~~~ts
type Unpack<T> = T extends Promise<infer V> ? V : T;
~~~`,options:[`Promise<User[]>`,`User`,`User[]`,`unknown`],correctIndex:2,explanation:"`infer V` выводит тип значения промиса — `User[]`. Встроенный `Awaited` работает так же, но рекурсивно."},{id:`enum-runtime`,prompt:`Почему во многих проектах вместо enum используют union литералов и объект as const?`,options:[`enum не поддерживается в Angular`,`enum генерирует код в рантайме, строковые enum не принимают обычные строки, хуже tree-shaking`,`union работает быстрее в рантайме`,`enum запрещён в strict-режиме`],correctIndex:1,explanation:"Union-литералы стираются при компиляции, совместимы со строками из JSON и шаблонов и подходят для режима «только стираемый синтаксис». Нужен список значений — объект/массив `as const` и выведенный из него тип."},{id:`no-unchecked-index`,prompt:`Что меняет флаг noUncheckedIndexedAccess?`,options:[`Запрещает доступ к массивам по индексу`,`Тип arr[i] и obj[key] становится T | undefined`,`Отключает проверку выхода за границы`,`Делает все массивы readonly`],correctIndex:1,explanation:"Без флага `users[0]` имеет тип `User`, хотя массив может быть пустым. С флагом — `User | undefined`, и компилятор заставляет обработать отсутствие значения."},{id:`branded`,prompt:`Какую проблему решают branded types?`,options:[`Ускоряют сравнение строк`,`Не позволяют перепутать значения одного примитивного типа с разным смыслом (UserId и OrderId)`,`Добавляют валидацию в рантайме автоматически`,`Заменяют классы`],correctIndex:1,explanation:"Структурная типизация считает все `string` одинаковыми. Фантомное поле `& { __brand: 'OrderId' }` делает типы несовместимыми, а «умный конструктор» с проверкой — единственное место создания значения."},{id:`decorators-angular`,prompt:`Нужен ли reflect-metadata для работы декораторов Angular?`,options:[`Да, без него не работает DI`,`Нет: AOT-компилятор превращает декораторы в статические определения (ɵcmp, ɵfac)`,`Только для @Injectable`,`Только в режиме разработки`],correctIndex:1,explanation:`Компилятор Angular читает метаданные декораторов и типы параметров из исходников при сборке и генерирует статические поля. В рантайме декораторы фактически не выполняются.`},{id:`private-vs-hash`,prompt:`Чем private из TypeScript отличается от поля #private?`,options:[`Ничем, #private — просто сокращённая запись`,`private проверяет только компилятор, а #private скрывает поле в рантайме: его нет в JSON.stringify и Object.keys`,`#private работает только в Angular`,`private доступен наследникам, а #private — нет`],correctIndex:1,explanation:"После компиляции `private` стирается, и поле становится обычным свойством: его видно в `JSON.stringify` и можно прочитать через `obj['field']`. `#field` — стандарт ECMAScript, приватность обеспечивает движок. Ни то ни другое наследникам не доступно. Подробнее — [Классы](/tracks/typescript/classes)."},{id:`private-other-instance`,prompt:`Скомпилируется ли метод equals?`,code:`~~~ts
class Point {
  constructor(private x: number) {}
  equals(other: Point) {
    return this.x === other.x;
  }
}
~~~`,options:[`Нет: к private-полю другого экземпляра обращаться нельзя`,`Да: private ограничивает доступ на уровне класса, а не экземпляра`,`Только с флагом strict: false`,`Только если x объявить как readonly`],correctIndex:1,explanation:"Приватность в TypeScript (как и в Java или C#) действует на уровне класса: внутри `Point` доступны private-члены любого экземпляра `Point`."},{id:`protected-access`,prompt:`Где доступен protected-член класса?`,options:[`Только внутри самого класса`,`Внутри класса и его наследников, но не снаружи`,`Везде, кроме других модулей`,`Только в статических методах`],correctIndex:1,explanation:"`protected` — для класса и наследников. В Angular так помечают члены компонента, которые нужны только шаблону: шаблон их видит, внешний код нет."},{id:`static-instance`,prompt:`Что выведет код?`,code:`~~~ts
class Counter {
  static total = 0;
  constructor() {
    Counter.total++;
  }
}
const c = new Counter();
new Counter();
console.log(Counter.total, (c as any).total);
~~~`,options:[`2 2`,`2 undefined`,`1 1`,`0 undefined`],correctIndex:1,explanation:"static-поле принадлежит конструктору `Counter`, а не экземплярам. Через `c` его не видно, поэтому `c.total` — `undefined`."},{id:`abstract-runtime`,prompt:`Что произойдёт, если создать экземпляр абстрактного класса из обычного JavaScript-кода?`,options:[`Движок бросит TypeError`,`Экземпляр создастся: abstract существует только на этапе компиляции`,`Вернётся undefined`,`Создастся экземпляр первого наследника`],correctIndex:1,explanation:"После компиляции абстрактный класс — обычный класс. Если нужна защита в рантайме, проверяйте `new.target` в конструкторе."},{id:`private-constructor`,prompt:`Зачем объявлять конструктор как private?`,options:[`Чтобы класс нельзя было наследовать и создать через new снаружи — экземпляры создаются только через static-методы (singleton, фабрика)`,`Чтобы ускорить создание объектов`,`Чтобы поля стали приватными автоматически`,`Это запрещено в TypeScript`],correctIndex:0,explanation:"С `private constructor` вызвать `new` можно только внутри класса, например в `static get instance()`. `protected constructor` запрещает прямое создание, но разрешает наследование."},{id:`override-keyword`,prompt:`Какую ошибку помогает поймать модификатор override вместе с noImplicitOverride?`,options:[`Вызов метода до конструктора`,`Ситуацию, когда метод в родителе переименовали или удалили, а наследник молча объявил новый метод`,`Утечку памяти в подписках`,`Неправильный тип возвращаемого значения в интерфейсе`],correctIndex:1,explanation:"С `override` компилятор проверяет, что в базовом классе есть такой член. `noImplicitOverride` делает слово обязательным, поэтому случайное переопределение тоже становится видно."}]},{trackId:`angular`,questions:[{id:`cd-how`,prompt:`Что делает Angular во время change detection?`,options:[`Перерисовывает весь DOM приложения`,`Обходит дерево view и сравнивает текущие значения биндингов с предыдущими, обновляя DOM при отличиях`,`Подписывается на каждое поле класса через Proxy`,`Сравнивает виртуальный DOM с реальным`],correctIndex:1,explanation:`Angular хранит предыдущие значения биндингов в LView и при проверке вычисляет выражения заново, обновляя только изменившиеся места. Виртуального DOM в Angular нет. Подробнее — [Как работает Change Detection](/tracks/angular/change-detection).`},{id:`onpush-default`,prompt:`Какая стратегия change detection используется по умолчанию в Angular 22?`,options:[`Default`,`OnPush`,`Eager`,`Zoneless`],correctIndex:1,explanation:"С Angular 22 компоненты без явной стратегии ведут себя как `OnPush`. Старая стратегия «проверять всегда» называется `Eager`, имя `Default` объявлено устаревшим. Zoneless — это способ планирования проверок, а не стратегия компонента."},{id:`onpush-triggers`,prompt:`Что из перечисленного НЕ приведёт к проверке OnPush-компонента?`,options:[`Новая ссылка в input от родителя`,`Клик по кнопке в шаблоне компонента`,`Изменение сигнала, прочитанного в шаблоне`,`Присваивание нового значения обычному полю в setTimeout`],correctIndex:3,explanation:"OnPush-компонент проверяется при новом input, событии из его шаблона, изменении сигнала из шаблона или явном `markForCheck()`. Присваивание поля в таймере Angular не видит — используйте сигнал."},{id:`zone-js-role`,prompt:`Какую роль играл zone.js в Angular?`,options:[`Изолировал стили компонентов`,`Патчил асинхронные API и сообщал Angular, когда запускать change detection`,`Отвечал за ленивую загрузку модулей`,`Реализовывал DI`],correctIndex:1,explanation:"zone.js перехватывает таймеры, промисы, события и XHR. Angular запускал `ApplicationRef.tick()` после каждой асинхронной задачи в NgZone. С Angular 21 новые приложения zoneless по умолчанию."},{id:`zoneless-notify`,prompt:`Как Angular узнаёт об изменениях в zoneless-режиме?`,options:[`Опрашивает компоненты каждые 16 мс`,`Через изменения сигналов из шаблона, markForCheck, события шаблона, setInput и операции с view`,`Через MutationObserver на document`,`Никак — нужно вручную вызывать detectChanges`],correctIndex:1,explanation:"Планировщик получает явные уведомления и объединяет их в один `tick()`. Поэтому код, который меняет обычные поля в колбэках, при переходе на zoneless переводят на сигналы."},{id:`expression-changed`,prompt:`Когда возникает ExpressionChangedAfterItHasBeenCheckedError?`,options:[`Когда input помечен как required, а значение не передано`,`Когда в dev-режиме проверочный проход видит, что значение биндинга изменилось после проверки`,`Когда сигнал записывается внутри computed`,`При любой ошибке в шаблоне`],correctIndex:1,explanation:`В режиме разработки Angular делает второй проход и сверяет значения. Изменение после проверки — симптом нарушения однонаправленного потока данных (например, ребёнок меняет состояние родителя в ngAfterViewInit).`},{id:`computed-vs-effect`,prompt:`Нужно вычислить полное имя из firstName и lastName. Что использовать?`,options:[`effect, который пишет в signal fullName`,`computed`,`ngOnChanges`,`BehaviorSubject`],correctIndex:1,explanation:"Производное значение — это `computed`: ленивое, мемоизированное, без побочных эффектов. `effect` для синхронизации сигналов между собой — антипаттерн; он нужен для внешнего мира (DOM вне Angular, storage, логи)."},{id:`linked-signal`,prompt:`Для чего нужен linkedSignal?`,options:[`Для двусторонней привязки к родителю`,`Для записываемого состояния, которое пересчитывается при смене источника, но может меняться вручную`,`Для связи сигнала с Observable`,`Для передачи сигнала между вкладками`],correctIndex:1,explanation:"Пример — выбранный элемент списка: при смене списка он сбрасывается на значение по умолчанию, а пользователь может выбрать другой через `set`."},{id:`di-resolution`,prompt:`Компонент внедряет CartService. В каком порядке Angular ищет провайдер?`,options:[`Сначала корневой инжектор, потом компонент`,`Элементные инжекторы от компонента вверх по дереву, затем инжекторы окружения (маршрут, root, platform)`,`Только в providers компонента`,`В порядке импортов в main.ts`],correctIndex:1,explanation:"Если нигде не найдено — `NullInjectorError` (или `null` с `optional: true`). Модификаторы `self`, `skipSelf`, `host` ограничивают путь поиска."},{id:`service-per-component`,prompt:`Как получить отдельный экземпляр сервиса для каждого экземпляра компонента?`,options:[`providedIn: "any"`,`Указать сервис в providers компонента`,`Вызывать new Service() в конструкторе`,`Использовать static поле`],correctIndex:1,explanation:`Элементный инжектор компонента создаст свой экземпляр, доступный компоненту и его потомкам, и уничтожит его вместе с компонентом (сработает ngOnDestroy сервиса).`},{id:`can-match`,prompt:`Чем canMatch отличается от canActivate?`,options:[`Ничем`,`canMatch участвует в сопоставлении: при false роутер ищет другие маршруты, а ленивый код не загружается`,`canMatch работает только с параметрами`,`canActivate вызывается раньше`],correctIndex:1,explanation:"`canActivate` вызывается после выбора маршрута и при false отменяет навигацию. `canMatch` удобен для ролевого доступа к ленивым разделам и альтернативных маршрутов на один путь."},{id:`for-track`,prompt:`Почему track item (по ссылке объекта) в @for плох для данных с сервера?`,code:`~~~html
@for (item of items(); track item) { <app-row [item]="item" /> }
~~~`,options:[`Это синтаксическая ошибка`,`Каждый ответ сервера — новые объекты, Angular пересоздаст весь DOM списка`,`track по объекту работает медленнее на 1%`,`Нельзя использовать объекты в шаблоне`],correctIndex:1,explanation:"По `track` Angular сопоставляет элементы между обновлениями. Используйте стабильный идентификатор: `track item.id`."},{id:`pure-pipe`,prompt:`Чистый пайп не пересчитался после items.push(newItem). Почему?`,options:[`Пайпы вызываются только при инициализации`,`Чистый пайп пересчитывается при смене ссылки входа, а push не меняет ссылку массива`,`Нужно добавить pure: true`,`Пайпы не работают с массивами`],correctIndex:1,explanation:"Решение — иммутабельное обновление (`[...items, newItem]`), а не превращение пайпа в нечистый: нечистый вызывается на каждой проверке."},{id:`constructor-vs-oninit`,prompt:`Где читать значение required input?`,options:[`В конструкторе`,`В ngOnInit или реактивно через computed/resource`,`В инициализаторе поля`,`Только в ngAfterViewInit`],correctIndex:1,explanation:`В конструкторе inputs ещё не установлены — чтение required signal input бросит ошибку. Конструктор и поля — для DI и создания сигналов.`},{id:`defer`,prompt:`Что делает блок @defer (on viewport)?`,options:[`Откладывает change detection блока`,`Выносит компоненты блока в отдельный чанк и загружает их, когда placeholder попадает в область видимости`,`Рендерит блок только на сервере`,`Кеширует блок в localStorage`],correctIndex:1,explanation:"Зависимости внутри `@defer` (standalone и не используемые вне блока) попадают в отдельный чанк. С `hydrate on ...` блок рендерится на сервере, а гидрируется по триггеру."},{id:`build-esbuild`,prompt:`Почему Angular CLI перешёл с Webpack на esbuild и Vite?`,options:[`Webpack перестал поддерживаться`,`Ради многократного ускорения сборки и dev-сервера, единого builder для SSR и меньшего числа зависимостей`,`Чтобы поддержать React`,`Из-за лицензии Webpack`],correctIndex:1,explanation:`esbuild написан на Go и параллелится, Vite даёт быстрый dev-сервер и HMR. Цена — нельзя расширять сборку Webpack-конфигом. Подробнее — [Почему Angular перешёл на esbuild и Vite](/tracks/tooling/angular-builders).`}]},{trackId:`rxjs`,questions:[{id:`switch-vs-others`,prompt:`Какой оператор выбрать для поиска с автокомплитом, чтобы устаревшие ответы не перезаписывали новые?`,options:[`mergeMap`,`concatMap`,`switchMap`,`exhaustMap`],correctIndex:2,explanation:"`switchMap` при новом значении отписывается от предыдущего внутреннего потока — HTTP-запрос отменяется. Подробнее — [операторы высшего порядка](/tracks/rxjs/higher-order)."},{id:`exhaust-submit`,prompt:`Пользователь многократно жмёт «Оплатить». Какой оператор защитит от повторных платежей?`,options:[`switchMap`,`exhaustMap`,`mergeMap`,`combineLatest`],correctIndex:1,explanation:"`exhaustMap` игнорирует новые значения, пока внутренний поток не завершился. `switchMap` отменил бы запрос на клиенте, но сервер мог уже списать деньги."},{id:`concat-order`,prompt:`Сохранения черновика должны уходить на сервер строго по порядку. Какой оператор?`,options:[`concatMap`,`switchMap`,`mergeMap`,`exhaustMap`],correctIndex:0,explanation:"`concatMap` ставит значения в очередь и подписывается на следующий внутренний поток только после завершения предыдущего."},{id:`hot-cold-http`,prompt:`В шаблоне три раза написано (user$ | async), где user$ = http.get(...). Сколько запросов уйдёт?`,options:[`1`,`3`,`0`,`Зависит от кеша браузера`],correctIndex:1,explanation:"HTTP-поток холодный: каждая подписка запускает отдельное выполнение. Решения: одна подписка через `@let`/`@if ... as`, `toSignal` или `shareReplay`."},{id:`combine-vs-fork`,prompt:`Чем forkJoin отличается от combineLatest?`,options:[`Ничем`,`forkJoin ждёт завершения всех и выдаёт последние значения один раз; combineLatest выдаёт при каждом изменении любого источника`,`forkJoin работает только с Subject`,`combineLatest ждёт завершения всех потоков`],correctIndex:1,explanation:"`forkJoin` — аналог `Promise.all` для конечных потоков (HTTP). С бесконечным потоком (valueChanges, BehaviorSubject) он никогда не выдаст значение."},{id:`combine-silent`,prompt:`combineLatest([a$, b$]) ничего не выдаёт, хотя a$ уже выдал значение. Вероятная причина?`,options:[`b$ ещё не выдал ни одного значения`,`combineLatest работает только с Promise`,`Нужно вызвать connect()`,`Значения выдаются только после complete`],correctIndex:0,explanation:"`combineLatest` ждёт хотя бы одно значение от каждого источника. Добавьте `startWith` или используйте `BehaviorSubject`."},{id:`catch-placement`,prompt:`Поиск перестал работать после первой сетевой ошибки. catchError стоит после switchMap. Как исправить?`,options:[`Добавить retry() в конец`,`Перенести catchError внутрь switchMap — на поток конкретного запроса`,`Заменить switchMap на mergeMap`,`Обернуть subscribe в try/catch`],correctIndex:1,explanation:"Ошибка — терминальное событие. `catchError` на внешнем потоке заменяет весь поток, и подписка на ввод пропадает. Внутри `switchMap` он заменяет только результат одного запроса."},{id:`behavior-vs-replay`,prompt:`Чем BehaviorSubject отличается от ReplaySubject(1)?`,options:[`Ничем`,`BehaviorSubject требует начальное значение и даёт getValue(); ReplaySubject(1) без начального значения`,`ReplaySubject нельзя завершить`,`BehaviorSubject хранит все значения`],correctIndex:1,explanation:"Подписчик `BehaviorSubject` сразу получает текущее значение. У `ReplaySubject(1)` до первого `next` подписчик ничего не получит."},{id:`share-replay-refcount`,prompt:`Чем опасен interval(1000).pipe(shareReplay(1)) в компоненте?`,options:[`Ничем`,`Без refCount: true подписка на interval останется после ухода всех подписчиков — утечка`,`shareReplay не работает с interval`,`Значения будут приходить дважды`],correctIndex:1,explanation:"`shareReplay(1)` эквивалентен `{ bufferSize: 1, refCount: false }`. Для бесконечных источников используйте `refCount: true`."},{id:`debounce-vs-throttle`,prompt:`Чем debounceTime(300) отличается от throttleTime(300)?`,options:[`Ничем`,`debounceTime ждёт 300 мс тишины и выдаёт последнее значение; throttleTime выдаёт первое и игнорирует остальные 300 мс`,`throttleTime работает только с кликами`,`debounceTime выдаёт первое значение`],correctIndex:1,explanation:"При непрерывном потоке событий `debounceTime` не выдаст ничего, а `throttleTime` будет выдавать регулярно."},{id:`take-until-order`,prompt:`Почему takeUntilDestroyed() нужно ставить последним в pipe?`,options:[`Это требование синтаксиса`,`Иначе операторы после него (например, switchMap) могут держать внутренние подписки после уничтожения компонента`,`Он не работает в начале pipe`,`Для производительности`],correctIndex:1,explanation:"Оператор отписывает поток выше себя. Внутренний поток `switchMap`, стоящего ниже, продолжит жить."},{id:`observable-vs-promise`,prompt:`Какое утверждение об Observable верно?`,options:[`Начинает выполняться сразу при создании`,`Всегда асинхронен`,`Ленив: выполняется при подписке, может выдать много значений и отменяется отпиской`,`Не может завершиться с ошибкой`],correctIndex:2,explanation:"Promise жадный, одно значение, без отмены. Observable ленивый, 0..∞ значений, может быть синхронным, отменяется `unsubscribe`."}]},{trackId:`web`,questions:[{id:`animate-props`,prompt:`Какие CSS-свойства лучше всего анимировать для плавности?`,options:[`width и height`,`top и left`,`transform и opacity`,`margin и padding`],correctIndex:2,explanation:"`transform` и `opacity` обрабатываются на этапе композиции (часто на GPU) без layout и paint. Изменение геометрии вызывает reflow."},{id:`layout-thrashing`,prompt:`Что такое layout thrashing?`,options:[`Слишком частая сборка мусора`,`Чередование записи стилей и чтения геометрии, вызывающее принудительный layout на каждой итерации`,`Ошибка CSS Grid`,`Мерцание шрифтов при загрузке`],correctIndex:1,explanation:`Сначала выполняйте все чтения (offsetHeight, getBoundingClientRect), затем все записи.`},{id:`inp`,prompt:`Что измеряет INP?`,options:[`Время до первого байта`,`Задержку от взаимодействия пользователя до следующей отрисовки`,`Сдвиги макета`,`Время загрузки самого большого изображения`],correctIndex:1,explanation:`INP (≤ 200 мс — хорошо) заменил FID. Улучшается дроблением длинных задач и облегчением обработчиков.`},{id:`cache-index`,prompt:`Какой Cache-Control правильный для index.html Angular-приложения?`,options:[`max-age=31536000, immutable`,`no-cache`,`public, max-age=86400`,`Не указывать заголовок`],correctIndex:1,explanation:"`index.html` ссылается на бандлы с хешами — он должен валидироваться при каждом заходе, иначе пользователи не получат новую версию. Хешированные бандлы — наоборот, `immutable` на год."},{id:`http2`,prompt:`Что главное даёт HTTP/2 по сравнению с HTTP/1.1?`,options:[`Шифрование`,`Мультиплексирование многих запросов в одном соединении и сжатие заголовков`,`Передачу по UDP`,`Поддержку WebSocket`],correctIndex:1,explanation:`HTTP/3 дополнительно переходит на QUIC (UDP) и убирает head-of-line blocking на уровне транспорта.`},{id:`sse-vs-ws`,prompt:`Нужно стримить ответ сервера (уведомления, токены LLM) только от сервера к клиенту. Что проще?`,options:[`WebSocket`,`Server-Sent Events или fetch-стриминг`,`Long polling каждые 100 мс`,`WebRTC`],correctIndex:1,explanation:`SSE работает поверх обычного HTTP, с автоматическим переподключением. WebSocket нужен для двустороннего обмена.`}]},{trackId:`security`,questions:[{id:`angular-xss`,prompt:`Как Angular защищает от XSS по умолчанию?`,options:[`Шифрует все строки`,`Экранирует интерполяцию и санитизирует значения в опасных контекстах (HTML, style, URL)`,`Запрещает innerHTML полностью`,`Использует CSP автоматически`],correctIndex:1,explanation:"Интерполяция выводит текст, `[innerHTML]` санитизируется, `javascript:`-URL блокируются, resource URL требуют явного доверия. Подробнее — [XSS](/tracks/security/xss)."},{id:`bypass`,prompt:`Когда допустимо использовать bypassSecurityTrustHtml?`,options:[`Чтобы убрать предупреждение «sanitizing HTML stripped some content»`,`Для HTML из полей пользователя`,`Только для доверенного значения: статической строки или результата надёжной санитизации по белому списку`,`Всегда, если данные пришли с нашего сервера`],correctIndex:2,explanation:"`bypass*` отключает защиту и ничего не проверяет. Каждое использование — с обоснованием и ревью."},{id:`csrf-angular`,prompt:`Как HttpClient помогает защититься от CSRF?`,options:[`Шифрует cookies`,`Читает cookie XSRF-TOKEN и отправляет её значение в заголовке X-XSRF-TOKEN для мутирующих запросов на свой origin`,`Блокирует запросы с других сайтов`,`Добавляет SameSite к cookies`],correctIndex:1,explanation:`Чужой сайт не может прочитать cookie вашего домена, а значит, не подставит заголовок. Проверку сравнения выполняет сервер.`},{id:`cors-fix`,prompt:`В консоли «blocked by CORS policy». Где это исправляется?`,options:[`Добавить заголовки Access-Control-* в запрос Angular`,`На сервере (или прокси с одним origin)`,`Отключить CORS в angular.json`,`Использовать JSONP`],correctIndex:1,explanation:"CORS — разрешение, которое выдаёт сервер заголовками ответа. В разработке помогает `proxy.conf.json`, в продакшене — reverse proxy или корректные заголовки."},{id:`token-storage`,prompt:`Главный риск хранения access-токена в localStorage?`,options:[`Он удалится при перезагрузке`,`Любой XSS может прочитать токен и использовать его вне вашего сайта`,`Его автоматически отправляет браузер`,`localStorage медленный`],correctIndex:1,explanation:`HttpOnly-cookie недоступна JS, но требует CSRF-защиты. Компромисс — access в памяти и refresh в HttpOnly-cookie; самый строгий — BFF.`},{id:`pkce`,prompt:`Какой OAuth-поток рекомендуется для SPA?`,options:[`Implicit flow`,`Password grant`,`Authorization Code + PKCE (или BFF)`,`Client credentials`],correctIndex:2,explanation:`Implicit flow устарел. PKCE защищает код авторизации от перехвата: без code_verifier код бесполезен.`},{id:`clickjacking`,prompt:`Какой заголовок защищает от clickjacking?`,options:[`Strict-Transport-Security`,`Content-Security-Policy: frame-ancestors 'none'`,`X-Content-Type-Options`,`Referrer-Policy`],correctIndex:1,explanation:"Устаревший аналог — `X-Frame-Options: DENY`. `frame-ancestors` работает только как HTTP-заголовок."},{id:`secrets-bundle`,prompt:`Можно ли хранить секретный API-ключ в environment.prod.ts?`,options:[`Да, файл не попадает в git`,`Да, если включить минификацию`,`Нет: всё в бандле публично`,`Да, Angular шифрует environment`],correctIndex:2,explanation:`Секреты живут на сервере. Браузеру отдаются только публичные ключи с ограничениями по домену и квоте.`}]},{trackId:`oop-solid`,questions:[{id:`srp`,prompt:`Как точнее всего сформулировать Single Responsibility Principle?`,options:[`У класса должен быть один метод`,`У модуля должна быть одна причина для изменения`,`Класс не должен иметь зависимостей`,`Файл не должен быть длиннее 100 строк`],correctIndex:1,explanation:`Модуль отвечает перед одним «актором» — группой людей, которая может потребовать изменений.`},{id:`ocp-angular`,prompt:`Какой механизм Angular лучше всего иллюстрирует Open/Closed Principle?`,options:[`ngOnInit`,`multi-провайдеры (интерсепторы, валидаторы)`,`ViewEncapsulation`,`@if`],correctIndex:1,explanation:`Новое поведение добавляется новым провайдером, а код, использующий токен, не меняется.`},{id:`lsp`,prompt:`Что является признаком нарушения LSP?`,options:[`Наследник добавляет новый метод`,`Наследник переопределяет метод и бросает «not supported», а клиенты проверяют instanceof`,`Класс реализует несколько интерфейсов`,`Использование абстрактного класса`],correctIndex:1,explanation:"Подтип должен заменять базовый тип без сюрпризов. Классический пример — изменяемый `Square extends Rectangle`."},{id:`isp`,prompt:`Компонент выпадающего списка зависит от репозитория с методами чтения, записи и экспорта, но использует только getAll. Какой принцип нарушен?`,options:[`DIP`,`ISP`,`OCP`,`DRY`],correctIndex:1,explanation:"Interface Segregation: клиенты не должны зависеть от методов, которые не используют. Выделите `Readable<T>`."},{id:`dip-vs-di`,prompt:`Чем Dependency Inversion отличается от Dependency Injection?`,options:[`Это одно и то же`,`DIP — принцип (зависеть от абстракций, которыми владеет верхний уровень), DI — техника передачи зависимостей извне`,`DI — принцип, DIP — библиотека`,`DIP применяется только на бэкенде`],correctIndex:1,explanation:`DI-контейнер Angular помогает реализовать DIP: компонент внедряет абстрактный токен, конфигурация подставляет реализацию.`},{id:`composition`,prompt:`Почему рекомендуют композицию вместо наследования?`,options:[`Наследование не поддерживается в TypeScript`,`Наследование создаёт жёсткую связь и взрыв иерархий; композиция собирает поведение из независимых частей`,`Композиция быстрее в рантайме`,`Так требует Angular`],correctIndex:1,explanation:`В Angular: сервисы в providers, hostDirectives, функции с inject() вместо базовых компонентов.`},{id:`private-hash`,prompt:`Чем #field отличается от private field в TypeScript?`,options:[`Ничем`,`#field — настоящая приватность движка, private — только проверка компилятора`,`private быстрее`,`#field доступен в шаблоне Angular`],correctIndex:1,explanation:"`private` стирается при компиляции и обходится через `obj['field']`. Ни то ни другое не доступно в шаблоне — для шаблона используйте `protected`."},{id:`dry`,prompt:`Две функции содержат одинаковое условие age >= 18: проверка совершеннолетия и разрешение продажи алкоголя. Стоит ли их объединить?`,options:[`Обязательно — это нарушение DRY`,`Не обязательно: код совпадает, но знания разные и меняются по разным причинам`,`Нужно вынести 18 в глобальную константу MAGIC`,`Нужно наследование`],correctIndex:1,explanation:`DRY — про дублирование знания, а не текста. Неправильная абстракция дороже дублирования.`}]},{trackId:`patterns`,questions:[{id:`interceptors`,prompt:`Какой паттерн лежит в основе HTTP-интерсепторов Angular?`,options:[`Singleton`,`Chain of Responsibility (и Decorator)`,`Builder`,`Iterator`],correctIndex:1,explanation:"Каждый интерсептор получает запрос и `next`, может изменить запрос, обработать ответ или ответить сам."},{id:`singleton-di`,prompt:`Как в Angular правильно получить единственный экземпляр сервиса на приложение?`,options:[`static getInstance()`,`providedIn: 'root'`,`Глобальная переменная window.service`,`Object.freeze`],correctIndex:1,explanation:`Единственность обеспечивает DI-конфигурация; зависимость явная и подменяемая в тестах.`},{id:`facade`,prompt:`Зачем фасад над NgRx Store?`,options:[`Чтобы ускорить селекторы`,`Чтобы компоненты зависели от простого API фичи, а не от actions и selectors`,`Чтобы отключить DevTools`,`Это обязательное требование NgRx`],correctIndex:1,explanation:`Фасад упрощает компоненты и тесты и позволяет сменить технологию стора без переписывания UI.`},{id:`strategy-angular`,prompt:`Что из перечисленного — пример паттерна Strategy в Angular?`,options:[`@Component`,`PreloadingStrategy / RouteReuseStrategy`,`ngOnDestroy`,`Renderer2`],correctIndex:1,explanation:`Взаимозаменяемые алгоритмы за общим интерфейсом, выбираемые конфигурацией.`},{id:`composite-forms`,prompt:`Где в Angular используется Composite?`,options:[`FormGroup / FormArray / FormControl`,`HttpClient`,`Router events`,`DomSanitizer`],correctIndex:0,explanation:"Все контролы — `AbstractControl`; `valid`, `value`, `reset` работают одинаково для поля и группы."},{id:`state-flags`,prompt:`Как избавиться от флагов isLoading, isError, isDone, которые дают невозможные комбинации?`,options:[`Добавить ещё один флаг isValid`,`Смоделировать состояние discriminated union и переходы функцией (конечный автомат)`,`Хранить флаги в localStorage`,`Использовать enum с битовыми флагами`],correctIndex:1,explanation:`Каждое состояние несёт только свои данные, недопустимые комбинации непредставимы. Это паттерн State.`},{id:`command-undo`,prompt:`Какой паттерн естественно реализует undo/redo?`,options:[`Observer`,`Command (или снимки — Memento)`,`Adapter`,`Proxy`],correctIndex:1,explanation:"Действие как объект с `execute`/`undo` и два стека; или хранение снимков иммутабельного состояния."},{id:`adapter-dto`,prompt:`Маппинг ответа API (snake_case, строки дат) в доменную модель — это какой паттерн?`,options:[`Adapter`,`Mediator`,`Template Method`,`Singleton`],correctIndex:0,explanation:`Адаптер на границе: формат бэкенда не протекает в компоненты, изменения API правятся в одном месте.`}]},{trackId:`architecture`,questions:[{id:`mvvm`,prompt:`На какой UI-паттерн больше всего похож Angular?`,options:[`MVC`,`MVVM`,`MVP`,`Flux`],correctIndex:1,explanation:`Шаблон — View, класс компонента — ViewModel, биндинги — связывание данных, сервисы — Model.`},{id:`dependency-rule`,prompt:`Что гласит правило зависимостей чистой архитектуры?`,options:[`UI зависит от базы данных`,`Зависимости направлены внутрь: домен не знает о фреймворке и инфраструктуре`,`Все слои зависят друг от друга`,`Инфраструктура определяет интерфейсы домена`],correctIndex:1,explanation:`Внутренние слои объявляют порты, внешние их реализуют; DI связывает их.`},{id:`bounded-context`,prompt:`Что такое bounded context в DDD?`,options:[`Область видимости переменной`,`Граница, внутри которой модель и термины предметной области однозначны`,`Модуль Angular`,`Транзакция базы данных`],correctIndex:1,explanation:`«Товар» в каталоге и на складе — разные модели. Во фронтенде контексты становятся границами фич и микрофронтендов.`},{id:`bff`,prompt:`Чем BFF отличается от API Gateway?`,options:[`Ничем`,`BFF — бэкенд под конкретный клиент, агрегирующий данные под его экраны; Gateway — общая точка входа (маршрутизация, auth, rate limit)`,`BFF работает только с GraphQL`,`Gateway пишет команда фронтенда`],correctIndex:1,explanation:`Часто используются вместе: клиент → BFF → gateway → сервисы.`},{id:`saga`,prompt:`Как обеспечить согласованность данных между микросервисами без распределённой транзакции?`,options:[`Двухфазный коммит во всех сервисах`,`Saga с компенсирующими действиями`,`Общая база данных`,`Синхронные вызовы с таймаутом`],correctIndex:1,explanation:`Локальные транзакции + компенсации; координация — хореографией событий или оркестратором.`},{id:`idempotency`,prompt:`Почему потребители сообщений из брокера должны быть идемпотентными?`,options:[`Для скорости`,`Стандартная гарантия — at-least-once: сообщение может прийти повторно`,`Kafka требует этого синтаксически`,`Чтобы не использовать базу данных`],correctIndex:1,explanation:`Дедупликация по id сообщения или Idempotency-Key делает повтор безопасным.`},{id:`microfrontends-when`,prompt:`Когда микрофронтенды оправданы?`,options:[`Всегда для новых проектов`,`Когда несколько независимых команд работают над большим продуктом и нужны независимые релизы`,`Когда приложение маленькое`,`Когда нужно ускорить загрузку страницы`],correctIndex:1,explanation:`Для 1–2 команд достаточно модульного монорепозитория. Микрофронтенды решают организационные задачи ценой технической сложности.`},{id:`circuit-breaker`,prompt:`Что делает Circuit Breaker в состоянии open?`,options:[`Повторяет запросы с увеличенной задержкой`,`Сразу отклоняет вызовы, не обращаясь к упавшему сервису, до истечения таймаута`,`Кеширует ответы`,`Балансирует нагрузку`],correctIndex:1,explanation:`После таймаута — half-open: пробный вызов решает, закрыть цепь или снова разомкнуть.`}]},{trackId:`tooling`,questions:[{id:`tree-shaking`,prompt:`Что мешает tree-shaking?`,options:[`ES-модули`,`CommonJS-зависимости и побочные эффекты на верхнем уровне модулей`,`Использование TypeScript`,`Ленивые маршруты`],correctIndex:1,explanation:`Tree-shaking опирается на статическую структуру import/export. Пакеты помечают отсутствие эффектов полем sideEffects: false.`},{id:`loader-plugin`,prompt:`Чем loader отличается от plugin в Webpack?`,options:[`Ничем`,`Loader преобразует отдельный файл при импорте, plugin работает с хуками всей компиляции`,`Plugin работает только с CSS`,`Loader выполняется после минификации`],correctIndex:1,explanation:`Цепочка loaders применяется справа налево: sass-loader → css-loader → style-loader.`},{id:`vite-dev`,prompt:`Почему dev-сервер Vite стартует быстро на больших проектах?`,options:[`Он кеширует всё в облаке`,`Он не собирает бандл: браузер грузит нативные ES-модули, а Vite трансформирует файлы по запросу`,`Он пропускает TypeScript`,`Он использует Webpack в фоне`],correctIndex:1,explanation:`Зависимости из node_modules один раз пред-собираются в ESM; HMR обновляет только изменённый модуль.`},{id:`nx-affected`,prompt:`Что делает nx affected -t test?`,options:[`Запускает все тесты`,`Запускает тесты изменённых проектов и всех, кто от них зависит`,`Запускает только упавшие тесты`,`Обновляет снапшоты`],correctIndex:1,explanation:`Nx сравнивает git-дифф с базой и обходит граф проектов. Плюс кеш по хешу входов.`},{id:`module-boundaries`,prompt:`Как запретить ui-библиотеке импортировать data-access в Nx?`,options:[`Договориться устно`,`Теги type:ui / type:data-access и правило @nx/enforce-module-boundaries`,`Удалить tsconfig paths`,`Вынести в отдельный репозиторий`],correctIndex:1,explanation:`Правило также запрещает глубокие импорты в обход index.ts и циклы между проектами.`},{id:`shared-singleton`,prompt:`Почему @angular/core в Module/Native Federation должен быть singleton?`,options:[`Чтобы бандл был меньше на 1 КБ`,`Два экземпляра Angular на странице дают разные DI и роутеры — NullInjectorError и неработающее приложение`,`Этого требует лицензия`,`Иначе не работает TypeScript`],correctIndex:1,explanation:`Плюс strictVersion: true — лучше явная ошибка при несовместимых версиях.`},{id:`native-federation`,prompt:`На чём основана Native Federation?`,options:[`На рантайме Webpack`,`На ES-модулях и import maps`,`На iframe`,`На Web Workers`],correctIndex:1,explanation:`Поэтому она работает со стандартной esbuild-сборкой Angular CLI, включая SSR.`},{id:`remote-entry`,prompt:`Зачем shell-приложению манифест с адресами remote-ов, читаемый при старте?`,options:[`Для SEO`,`Чтобы один собранный shell работал в любом окружении, а remote можно было откатить сменой URL`,`Для ускорения сборки`,`Чтобы отключить кеширование`],correctIndex:1,explanation:`Динамическая федерация: адреса не зашиты в бандл.`}]},{trackId:`ai-mcp`,questions:[{id:`mcp-what`,prompt:`Какую проблему решает Model Context Protocol?`,options:[`Ускоряет инференс моделей`,`Стандартизирует подключение AI-приложений к инструментам и данным: N×M интеграций превращаются в N+M`,`Шифрует промпты`,`Заменяет REST API`],correctIndex:1,explanation:`Сервис реализует MCP-сервер один раз и работает со всеми совместимыми клиентами.`},{id:`primitives`,prompt:`Кто управляет вызовом tools в MCP?`,options:[`Пользователь`,`Модель (с разрешения host-а)`,`Сервер сам по таймеру`,`Браузер`],correctIndex:1,explanation:`Tools — для модели, resources — для приложения, prompts — для пользователя.`},{id:`transports`,prompt:`Какой транспорт используют локальные MCP-серверы вроде Angular CLI MCP?`,options:[`WebSocket`,`stdio`,`gRPC`,`SMTP`],correctIndex:1,explanation:`Host запускает сервер дочерним процессом. Удалённые серверы используют Streamable HTTP с OAuth 2.1.`},{id:`stdio-log`,prompt:`Почему в stdio MCP-сервере нельзя писать console.log?`,options:[`console.log запрещён в Node.js`,`stdout занят сообщениями протокола — лишний вывод сломает обмен; логи пишут в stderr`,`Это раскроет токены`,`Это замедлит сервер`],correctIndex:1,explanation:`Используйте console.error или логгер в файл.`},{id:`stateless`,prompt:`Что принципиально изменилось в ревизии MCP 2026-07-28?`,options:[`Протокол перешёл на XML`,`Протокол стал stateless: нет handshake initialize и сессий, возможности — через server/discover`,`Удалены tools`,`Требуется WebSocket`],correctIndex:1,explanation:`Любой экземпляр сервера обслуживает любой запрос — проще масштабирование за балансировщиком.`},{id:`tool-error`,prompt:`Инструмент не нашёл задачу по id. Как вернуть ошибку?`,options:[`JSON-RPC error с кодом -32601`,`Результат с isError: true и понятным текстом — чтобы модель увидела ошибку и исправилась`,`Закрыть соединение`,`Вернуть пустую строку`],correctIndex:1,explanation:`JSON-RPC ошибки — для проблем протокола (неизвестный метод, неверные параметры запроса).`},{id:`lethal-trifecta`,prompt:`Какое сочетание делает prompt injection особенно опасной?`,options:[`Медленная сеть и большой контекст`,`Доступ к приватным данным + недоверенный контент + возможность отправить данные наружу`,`Использование TypeScript и Zod`,`Локальный сервер и stdio`],correctIndex:1,explanation:`Уберите хотя бы один элемент триады — утечка станет невозможной. Надёжной фильтрации инъекций не существует.`},{id:`angular-mcp`,prompt:`Что даёт подключение Angular CLI MCP-сервера к ассистенту в IDE?`,options:[`Автоматический деплой`,`Актуальные best practices и документацию вашей версии, сведения о проектах, запуск сборки/тестов, план миграции на zoneless`,`Доступ к продакшен-базе`,`Генерацию дизайна`],correctIndex:1,explanation:`Флаги --read-only и --local-only ограничивают набор инструментов.`}]}];var y=new I(`QUIZ_REGISTRY`,{providedIn:`root`,factory:()=>f});var h=class e{quizzes=h$1(y);find(o){return this.quizzes.find(t=>t.trackId===o)}static ɵfac=function(t){return new(t||e)};static ɵprov=_({token:e,factory:e.ɵfac,providedIn:`root`})};export{h as t};